const txt = a => (a || []).map(t => t.plain_text).join("");
const now = Date.now();
const rows = [];
for (const it of $('Notion Activity Log').all()) {
  const p = it.json.properties || {};
  if (!p["Agent"]) continue;
  const ts = p["Timestamp"]?.date?.start || it.json.created_time;
  rows.push({ agent: p["Agent"]?.select?.name || "Unknown", status: p["Status"]?.select?.name || "", t: Date.parse(ts) || 0, task: txt(p["Task"]?.title) });
}
// Ignore our own rows so the monitor cannot mask silence or alert on itself.
const recent = rows.filter(r => r.agent !== "Shield/Ops").sort((a, b) => b.t - a.t).slice(0, 200);
let war = false;
for (const it of $('Notion System Flags').all()) {
  const p = it.json.properties || {};
  let title = "";
  for (const k in p) if (p[k].type === "title") title = txt(p[k].title);
  if (/^war mode$/i.test(title.trim())) war = p["Value"]?.checkbox === true;
}
const findings = [];
let level = 0; // 0 OK, 1 WARN, 2 ALERT
const bump = (l, msg) => { level = Math.max(level, l); findings.push(msg); };
const HOUR = 3600e3, STUCK = 30 * 60e3;
// 1. Errors in the last hour per agent (1-2 WARN, 3+ ALERT)
const errs = {};
for (const r of recent) if (r.status === "Error" && now - r.t <= HOUR) errs[r.agent] = (errs[r.agent] || 0) + 1;
for (const a in errs) bump(errs[a] >= 3 ? 2 : 1, `${a}: ${errs[a]} error(s) in the last hour. Recommend Joshua review; consider pausing ${a}.`);
// 2. Stuck agents: latest row is Working/Thinking for over 30 min (over 2h is ALERT)
const latest = {};
for (const r of recent) if (!latest[r.agent]) latest[r.agent] = r;
for (const a in latest) {
  const r = latest[a], age = now - r.t;
  if ((r.status === "Working" || r.status === "Thinking") && age > STUCK)
    bump(age > 4 * STUCK ? 2 : 1, `${a}: stuck in ${r.status} for ${Math.round(age / 60000)} min ("${r.task}"). Recommend checking or pausing ${a}.`);
}
// 3. Silence
if (recent.length === 0 || now - recent[0].t > 24 * HOUR)
  bump(2, "No Activity Log rows in over 24h (possible silent failure of the agents or the logging path).");
const status = ["OK", "WARN", "ALERT"][level];
const summary = findings.length ? findings.join(" | ") : "No problems found.";
return [{ json: { status, findings, war_mode: war, rows_checked: recent.length, summary: summary + (war ? " (War Mode is ON; read-only check, nothing changed.)" : ""), checked_at: new Date().toISOString() } }];
